INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (1, 0, 10, 'article', '[DEMO] 成瘾行为改变入门指南', 'https://picsum.photos/seed/help-article-1/400/240', 'https://example.com/materials/guide-intro', '这是一篇用于联调的教育素材示例内容。', 1, 66, 1, '2026-03-06 19:44:58', '2026-03-13 18:24:12', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (2, 0, 12, 'video', '[DEMO] 冲动应对技巧视频课', 'https://picsum.photos/seed/help-video-1/400/240', 'https://example.com/materials/skill-video-1.mp4', '', 1, 17, 1, '2026-03-06 19:44:58', '2026-03-12 18:10:33', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (3, 0, 14, 'pdf', '[DEMO] 家属沟通手册', 'https://picsum.photos/seed/help-pdf-1/400/240', 'https://example.com/materials/family-handbook.pdf', '', 1, 10, 1, '2026-03-06 19:44:58', '2026-03-11 16:10:14', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (4, 0, 15, 'link', '[DEMO] 正念训练推荐书单', 'https://picsum.photos/seed/help-book-1/400/240', 'https://example.com/entertainment/books/mindfulness', '娱乐内容示例：书籍推荐。', 1, 36, 1, '2026-03-06 19:44:58', '2026-03-13 19:14:08', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (5, 5, 10, 'pdf', '[DEMO] 我的私人康复记录', 'https://picsum.photos/seed/private-pdf-1/400/240', 'https://example.com/private/recovery-record.pdf', '私人素材示例。', 0, 3, 1, '2026-03-06 19:44:58', '2026-03-06 19:44:58', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (6, 0, 10, 'article', '戒断初期的 7 天自救清单', '/static/images/image 861.png', '', '第一天先做减法，不要急着要求自己完全恢复正常。\n先保证喝水、进食、睡眠和固定作息，把身体从混乱里慢慢拉回来。\n当渴求出现时，不要和它正面硬扛，先延迟十分钟，再做一件替代动作，比如洗脸、快走、给支持者发消息。\n把每天能完成的目标压缩到三件事以内，小目标完成后再追加。', 1, 101, 1, '2026-02-28 01:52:32', '2026-03-11 15:49:42', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (7, 0, 11, 'article', '为什么你会反复想起过去的使用场景', '/static/images/image 872.png', '', '很多复吸冲动并不是突然出现，而是由环境线索、情绪记忆和身体反应共同触发。\n当你路过熟悉地点、听到熟悉音乐，甚至闻到某种味道时，大脑会自动唤起旧的奖赏回路。\n理解这一点不是为了放弃，而是为了提前识别高风险场景，减少临时被动应对。\n你需要做的是把高风险场景写下来，并给每个场景准备一个替代方案。', 1, 87, 1, '2026-03-01 01:52:32', '2026-03-11 16:09:38', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (8, 0, 12, 'video', '情绪高压时的 3 分钟呼吸练习', '/static/images/image 861.png', 'https://example.com/material/breathing-video', '先把注意力收回到身体，双脚踩实地面。\n吸气四秒，停顿两秒，呼气六秒，连续做六轮。\n如果脑子里仍然很乱，就把注意力转移到你眼前能看到的三样东西。', 1, 133, 1, '2026-03-02 01:52:32', '2026-03-12 18:10:37', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (9, 0, 13, 'pdf', '复发预警信号检查表', '/static/images/image 872.png', 'https://example.com/material/relapse-checklist.pdf', '当你开始频繁失眠、烦躁、回避支持者、觉得一次也没关系时，往往已经进入危险边缘。\n这份检查表用于帮助你在问题真正扩大前发现变化。\n建议每周固定做一次自查，并把结果发给医生或家属共同复盘。', 1, 76, 1, '2026-03-03 01:52:32', '2026-03-13 11:00:54', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (10, 0, 14, 'article', '家属沟通时最容易踩的 4 个坑', '/static/images/image 815.png', '', '第一，不要把所有对话都变成审问。\n第二，不要在对方情绪最差的时候逼他讲道理。\n第三，不要把监督当成支持，真正的支持需要边界和节奏。\n第四，家属也要有自己的恢复空间，否则很容易一起被拖进耗竭。', 1, 110, 1, '2026-03-04 01:52:32', '2026-03-11 16:10:06', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (11, 0, 12, 'audio', '夜间渴求出现时，可以听的稳定音频', '/static/images/image 861.png', 'https://example.com/material/night-audio.mp3', '夜里最容易被放大的不是问题本身，而是孤立感。\n这段音频不是替你解决所有问题，而是帮助你在最难熬的十分钟里稳住节奏。\n建议戴耳机、调暗灯光，配合慢呼吸一起使用。', 1, 63, 1, '2026-03-05 01:52:32', '2026-03-11 16:09:43', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (12, 0, 15, 'article', '在情绪低谷时也能读完的小书单', '/static/images/image 872.png', '', '这份书单适合在注意力不稳定、情绪起伏较大的阶段慢慢读。\n它们不会给你太多压力，而是用更温和的方式帮你把注意力从冲动里拉回来。\n先读完一小段，再决定要不要继续，这比强迫自己一口气读完更有效。', 1, 58, 1, '2026-03-02 02:25:22', '2026-03-02 02:25:22', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (13, 0, 15, 'pdf', '睡前十分钟阅读手册', '/static/images/image 882.png', 'https://example.com/entertainment/reading-handbook.pdf', '如果你最近总在夜里胡思乱想，可以尝试把睡前十分钟交给更稳定的阅读节奏。\n这份手册不是为了追求效率，而是帮你从高刺激内容里退出来。\n你不需要一次做很多，只需要每天都做一点。', 1, 75, 1, '2026-03-03 02:25:22', '2026-03-13 14:45:14', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (14, 0, 16, 'video', '适合恢复期观看的治愈电影清单', '/static/images/image 861.png', 'https://example.com/entertainment/movie-healing.mp4', '有些电影不会替你解决问题，但能在最紧绷的时候给你一点喘息空间。\n这份清单挑的是情绪负担更低、节奏更稳的作品。\n如果你最近很容易被刺激内容带偏，优先从轻一点的片子开始。', 1, 101, 1, '2026-03-04 02:25:22', '2026-03-13 14:45:17', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (15, 0, 17, 'audio', '夜晚独处时可以循环的舒缓歌单', '/static/images/entertainment/music-cover.png', 'https://example.com/entertainment/night-playlist.mp3', '独处并不总是危险的，关键是你给自己放进来的内容是什么。\n这组音乐更适合在夜里情绪起伏明显的时候播放。\n不要期待它立刻改变你，但它可以帮你把呼吸和节奏慢慢放下来。', 1, 125, 1, '2026-03-05 02:25:22', '2026-03-13 14:45:20', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (16, 0, 18, 'link', '低压力休闲小游戏推荐', '/static/images/entertainment/game-cover-a.png', 'https://example.com/entertainment/relax-game', '当大脑一直处在高压和高刺激里时，简单、低门槛的小游戏有时反而能起到切换状态的作用。\n关键不是沉迷，而是给自己一段有限、可控、不会继续耗竭的放松时间。\n建议给娱乐设定明确时长，玩完就停。', 1, 51, 1, '2026-03-06 02:25:22', '2026-03-14 19:45:41', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (17, 0, 18, 'link', '专注恢复训练小游戏合集', '/static/images/entertainment/game-cover-b.png', 'https://example.com/entertainment/focus-game', '如果你最近总觉得注意力散、做什么都坐不住，可以先从短时专注训练开始。\n这类小游戏的价值不在于通关，而在于帮你重新建立一点点可持续的专注感。\n每次十分钟就够，不要把放松再次变成任务。', 1, 61, 1, '2026-03-06 14:25:22', '2026-03-14 19:45:43', NULL);
INSERT INTO `sa_content_material` (`id`, `member_id`, `category_id`, `media_type`, `title`, `cover_url`, `content_url`, `content_text`, `is_public`, `view_count`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (18, 11, 10, 'link', 'QA 私人素材', 'https://example.com/cover.png', 'https://example.com/private-material', 'QA 私人素材说明', 0, 0, 0, '2026-03-10 13:01:49', '2026-03-10 13:01:49', '2026-03-10 13:01:49');
