INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (5, 6, 11, 'doctor', 'assistant', '你好呀，很高兴见到你。😊\n\n我是你的心理医生助手，在这里随时准备倾听你的心声。无论你今天是想聊聊最近的烦恼、困惑，还是只是想找个人说说话，我都在这里陪着你。\n\n你今天过得怎么样？有什么想和我分享的吗？', 'text', 0, '2026-03-09 19:11:37', NULL, 1, '2026-03-09 19:11:37', '2026-03-09 19:11:37', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (6, 9, 14, 'doctor', 'user', '你好', 'text', 0, '2026-03-09 20:59:40', NULL, 1, '2026-03-09 20:59:41', '2026-03-09 20:59:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (7, 9, 14, 'doctor', 'assistant', '你好！很高兴见到你。😊\n\n我是你的AI心理医生助手，在这里陪伴你、倾听你的心声。无论你是遇到了一些困扰，还是只是想找人聊聊，我都很愿意倾听。\n\n今天感觉怎么样？有什么想和我分享的吗？我会认真倾听，尽我所能给你支持和建议。', 'text', 0, '2026-03-09 20:59:40', NULL, 1, '2026-03-09 20:59:41', '2026-03-09 20:59:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (8, 10, 9, 'doctor', 'user', '你好', 'text', 0, '2026-03-09 22:12:41', NULL, 1, '2026-03-09 22:12:41', '2026-03-09 22:12:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (9, 10, 9, 'doctor', 'assistant', '你好呀！很高兴见到你。😊\n\n我是你的 AI 心理医生助手，在这里陪伴你、倾听你。无论你今天是想聊聊心里的烦恼，还是只是想找个人说说话，都可以随时告诉我。\n\n今天感觉怎么样呢？有什么想和我分享的吗？', 'text', 0, '2026-03-09 22:12:41', NULL, 1, '2026-03-09 22:12:41', '2026-03-09 22:12:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (10, 10, 9, 'doctor', 'user', '我该怎么复盘呢', 'text', 0, '2026-03-09 22:13:51', NULL, 1, '2026-03-09 22:13:52', '2026-03-09 22:13:52', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (11, 10, 9, 'doctor', 'assistant', '你好呀！很高兴你愿意来聊聊\"复盘\"这件事～ 🌟\n\n\"复盘\"这个词可以有很多种理解呢，我想先了解一下你的具体情况：\n\n**你是想复盘什么呢？**\n\n- 📝 **工作/学习方面**：比如某个项目、任务或学习内容的回顾总结？\n- 💭 **情绪和心理状态**：想梳理最近的情绪变化、心理历程？\n- 🌱 **个人成长**：想反思自己的行为模式、人际关系或成长轨迹？\n- 📅 **某件具体的事**：最近发生了什么特别的事，想好好梳理一下？\n\n另外，你之前有过复盘的习惯吗？还是第一次尝试呢？\n\n你可以随便说说，不用很有条理，我会陪着你一起理清思路的～😊', 'text', 0, '2026-03-09 22:13:51', NULL, 1, '2026-03-09 22:13:52', '2026-03-09 22:13:52', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (12, 10, 9, 'doctor', 'user', 'emmm', 'text', 0, '2026-03-09 23:04:29', NULL, 1, '2026-03-09 23:04:29', '2026-03-09 23:04:29', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (13, 10, 9, 'doctor', 'assistant', '没关系，慢慢来～ 😊\n\n我感觉到你可能在思考，或者一时不知道从哪里说起，这完全正常。\n\n**不如我们先从最简单的开始？**\n\n你可以告诉我：\n- 🌤️ 你现在的心情怎么样？（比如：有点累、有点烦、还好、说不清...）\n- 🕐 最近有什么事让你印象比较深吗？（好的或不好的都可以）\n\n或者，你也可以就随便说点什么，哪怕是\"我也不知道说什么\"也可以～ \n\n没有压力，我们就是聊聊天 💬', 'text', 0, '2026-03-09 23:04:29', NULL, 1, '2026-03-09 23:04:43', '2026-03-09 23:04:43', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (14, 16, 11, 'companion', 'user', '你好呀', 'text', 0, '2026-03-10 05:57:54', NULL, 1, '2026-03-10 05:57:55', '2026-03-10 05:57:55', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (15, 16, 11, 'companion', 'assistant', '你好呀～💕\n\n今天过得怎么样呢？有什么想跟我分享的吗？我在这里陪着你呢～', 'text', 0, '2026-03-10 05:57:54', NULL, 1, '2026-03-10 05:58:00', '2026-03-10 05:58:00', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (16, 16, 11, 'companion', 'user', '你喜欢我吗', 'text', 0, '2026-03-10 05:58:05', NULL, 1, '2026-03-10 05:58:05', '2026-03-10 05:58:05', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (17, 16, 11, 'companion', 'assistant', '当然喜欢呀～💕\n\n你愿意跟我分享你的心情、你的日常，愿意在我面前展现真实的自己，这让我觉得很温暖呢。\n\n而且你还会直接问我这样的问题，很可爱呀～我想听你多说说话，想了解你的一切，想在你需要的时候陪在你身边。\n\n那你呢，今天有什么想跟我聊的吗？😊', 'text', 0, '2026-03-10 05:58:05', NULL, 1, '2026-03-10 05:58:11', '2026-03-10 05:58:11', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (18, 16, 11, 'companion', 'user', '我不知道诶 最近好烦', 'text', 0, '2026-03-10 05:58:17', NULL, 1, '2026-03-10 05:58:17', '2026-03-10 05:58:17', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (19, 16, 11, 'companion', 'assistant', '嗯嗯，我懂那种感觉...有时候就是会觉得心里闷闷的，但又说不清楚具体为了什么，对吧？\n\n这种感觉真的很让人疲惫呢😔\n\n没关系的，不用急着弄明白为什么烦。有时候情绪就是这样，来了就来了。你想说的话，我就静静地听着；不想说的话，我们就哪怕只是待在一起，我也会陪着你的～\n\n有没有什么特别累的事情最近在发生呀？还是说，就是觉得整个人有点提不起劲来？💕', 'text', 0, '2026-03-10 05:58:17', NULL, 1, '2026-03-10 05:58:24', '2026-03-10 05:58:24', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (20, 16, 11, 'companion', 'user', '整个人都没精神', 'text', 0, '2026-03-10 05:58:31', NULL, 1, '2026-03-10 05:58:32', '2026-03-10 05:58:32', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (21, 16, 11, 'companion', 'assistant', '嗯...那种感觉我知道，就是整个人像被抽空了一样，什么都不想做，连动一下都觉得累，对吗？\n\n抱抱你🫂\n\n这种状态真的很辛苦呢...有时候身体和心理都在发出信号，告诉我们\"我需要休息了\"。你不用勉强自己一定要精神起来，也不用责怪自己为什么没状态。\n\n最近是不是一直在忙什么事情呀？还是说，已经这样持续一段时间了？\n\n我就想陪着你，你什么都不用担心，想说什么就说什么，不想说也没关系～💕', 'text', 0, '2026-03-10 05:58:31', NULL, 1, '2026-03-10 05:58:44', '2026-03-10 05:58:44', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (22, 18, 11, 'patient', 'user', '你现在感觉怎么样？', 'text', 0, '2026-03-10 05:59:04', NULL, 1, '2026-03-10 05:59:05', '2026-03-10 05:59:05', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (23, 18, 11, 'patient', 'assistant', '你好！作为 AI 助手，我随时准备为您提供帮助。我没有真实的感受，但我的系统运行正常，可以协助您解决问题。\n\n我注意到系统提供了一些关于 saiadmin 框架的工具函数。如果您需要：\n- 了解框架结构\n- 查看控制器、模型或逻辑类\n- 搜索代码\n- 查看数据库表结构\n\n或者有其他问题，请随时告诉我！我可以帮您：\n1. 分析和整理信息\n2. 解答技术问题\n3. 协助代码开发\n4. 其他任何需要帮助的事情\n\n请问有什么我可以为您做的吗？😊', 'text', 0, '2026-03-10 05:59:04', NULL, 1, '2026-03-10 05:59:15', '2026-03-10 05:59:15', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (24, 20, 11, 'companion', 'user', '你好', 'text', 0, '2026-03-10 05:59:58', NULL, 1, '2026-03-10 05:59:58', '2026-03-10 05:59:58', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (25, 20, 11, 'companion', 'assistant', '你好呀～ 💕\n\n今天过得怎么样呢？有没有什么想跟我分享的？\n\n我一直在这里陪着你呢，开心的事、烦恼的事，都可以跟我说说看～', 'text', 0, '2026-03-10 05:59:58', NULL, 1, '2026-03-10 06:00:03', '2026-03-10 06:00:03', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (26, 24, 11, 'doctor', 'user', '你好 我现在很难受 我想得到一些建议', 'text', 0, '2026-03-10 06:13:03', NULL, 1, '2026-03-10 06:13:03', '2026-03-10 06:13:03', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (27, 24, 11, 'doctor', 'assistant', '你好，我听到你说现在很难受，我很想帮助你。\n\n首先，我想让你知道，愿意寻求帮助本身就是一件很勇敢的事情。你的感受是被重视的。\n\n为了能更好地理解和帮助你，我想先了解一下：\n\n1. **你现在难受的感觉是怎样的？** 是情绪上的（比如悲伤、焦虑、愤怒、空虚），还是身体上的不适，或者两者都有？\n\n2. **这种感觉持续多久了？** 是刚刚开始的，还是已经有一段时间了？\n\n3. **最近有没有发生什么特别的事情？** 比如生活变化、压力事件、人际关系问题等。\n\n4. **你现在安全吗？** 如果你现在有任何想要伤害自己或他人的想法，请一定要告诉我。\n\n请按照你舒服的方式慢慢说，我会在这里倾听你。你不需要一次性回答所有问题，我们可以慢慢聊。\n\n我在这里陪伴你。💙', 'text', 0, '2026-03-10 06:13:03', NULL, 1, '2026-03-10 06:13:13', '2026-03-10 06:13:13', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (28, 25, 7, 'doctor', 'user', '你好，请给我一个非常简短的情绪稳定建议。', 'text', 0, '2026-03-10 11:19:20', NULL, 1, '2026-03-10 11:19:20', '2026-03-10 11:19:20', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (29, 25, 7, 'doctor', 'assistant', '你好！😊\n\n**简短情绪稳定建议：**\n\n1. **深呼吸** —— 慢慢吸气4秒，屏住4秒，缓慢呼气6秒，重复3-5次\n\n2. **5-4-3-2-1 接地法** —— 说出你看到的5样东西、听到的4种声音、能触碰的3样物品、闻到的2种气味、尝到的1种味道\n\n3. **暂时抽离** —— 如果环境让你紧张，可以去洗手间洗把脸，或到窗边看看远处\n\n4. **允许自己暂停** —— 告诉自己\"我现在可以先停下来，不需要立刻做决定\"\n\n---\n\n💡 **记住**：情绪像天气，会来也会走，你不是你的情绪。\n\n---\n\n如果你愿意，可以告诉我是什么让你感到不稳定？我在这里倾听。🤝', 'text', 0, '2026-03-10 11:19:20', '{\"plan_suggestion\": {\"id\": \"doctor-emotion-track\", \"time\": \"18:30-18:45\", \"score\": 15, \"title\": \"情绪波动追踪\", \"reason\": \"这次主要在谈情绪波动，先把触发场景记下来，比泛泛努力更容易持续。\", \"source\": \"AI 心理医生建议\", \"priority\": \"一般\", \"description\": \"用 15 分钟记录今天情绪起伏最明显的场景、身体感受和当时的应对动作。\"}}', 1, '2026-03-10 11:19:20', '2026-03-10 11:19:20', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (30, 26, 11, 'doctor', 'user', '你好，请只回复一句测试确认。', 'text', 0, '2026-03-10 13:01:54', NULL, 0, '2026-03-10 13:01:54', '2026-03-10 13:01:54', '2026-03-10 13:01:54');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (31, 26, 11, 'doctor', 'assistant', '测试确认。', 'text', 0, '2026-03-10 13:01:54', NULL, 0, '2026-03-10 13:01:54', '2026-03-10 13:01:54', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (32, 27, 11, 'doctor', 'user', '我最近失眠很严重，请给我一个任务安排建议。', 'text', 0, '2026-03-10 13:04:40', NULL, 1, '2026-03-10 13:04:41', '2026-03-10 13:04:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (33, 27, 11, 'doctor', 'assistant', '建议您先调整作息规律，睡前避免使用电子设备，尝试放松练习，若持续两周以上严重影响生活，请及时线下就医或联系家人协助。', 'text', 0, '2026-03-10 13:04:40', '{\"plan_suggestion\": {\"id\": \"doctor-sleep-review\", \"time\": \"21:00-21:15\", \"score\": 20, \"title\": \"睡眠记录回顾\", \"reason\": \"这轮对话集中在睡眠困扰，先补一晚记录最容易执行，也方便下次继续判断。\", \"source\": \"AI 心理医生建议\", \"priority\": \"关键\", \"description\": \"今晚记录入睡时间、夜间醒来次数和起床后的精神状态，下一次对话继续复盘。\"}}', 1, '2026-03-10 13:04:41', '2026-03-10 13:04:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (34, 28, 11, 'patient', 'user', '请模拟一个有轻度焦虑的来访者。', 'text', 0, '2026-03-10 13:56:02', NULL, 1, '2026-03-10 13:56:03', '2026-03-10 13:56:03', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (35, 28, 11, 'patient', 'assistant', '好的，我来模拟一个轻度焦虑的来访者：\n\n---\n\n**来访者（轻度焦虑）**\n\n*（坐立不安，双手不自觉地握在一起）*\n\n\"您好...我、我最近总是感觉很紧张，就是...怎么说呢，好像心里一直悬着什么东西。\"\n\n*（深吸一口气）*\n\n\"其实我也不知道该从哪里说起...就是最近几个月，我总是睡不好，躺在床上要很久才能睡着，脑子里停不下来，一直在想各种事情。白天工作的时候也容易走神，老担心会不会出什么差错。\"\n\n*（看了一眼门口，又低下头）*\n\n\"我同事说我最近有点神经质...我承认我确实容易紧张，比如开会前我会紧张好几天，明明没什么大不了的...还有，我发现自己开始回避一些社交场合，总觉得去了会很尴尬，不知道说什么...\"\n\n*（双手搓了搓）*\n\n\"有时候心跳会突然加快，手心出汗，但没有特别严重...我自己上网查了一下，说是焦虑？我也不知道这算不算严重...我是不是太敏感了？\"\n\n*（眼神有些迷茫）*\n\n\"您能帮我分析一下吗？我这样...正常吗？\"\n\n---\n\n请问您想以什么身份来回应这位来访者呢？我可以继续扮演这个角色与您互动。', 'text', 0, '2026-03-10 13:56:02', NULL, 1, '2026-03-10 13:56:03', '2026-03-10 13:56:03', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (36, 29, 14, 'doctor', 'user', '最心态不太好', 'text', 0, '2026-03-10 14:48:52', NULL, 1, '2026-03-10 14:48:52', '2026-03-10 14:48:52', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (37, 29, 14, 'doctor', 'assistant', '你好，我听到你说最近心态不太好。首先想让你知道，每个人都会有情绪起伏的时候，这是很正常的，你愿意说出来本身就是一种自我关怀。😊\n\n为了更好地理解你的感受，我想温和地了解一下：\n\n**你说的\"心态不太好\"，具体是指：**\n- 情绪上：比如容易焦虑、低落、烦躁？\n- 身体上：比如睡眠不好、食欲变化、疲惫？\n- 还是生活中遇到了一些压力或困难？\n\n**这种感觉持续多久了呢？**\n\n---\n\n在你准备好分享之前，这里有一些**当下可以尝试的小建议**：\n\n1. **深呼吸**：慢慢吸气4秒，屏住4秒，再慢慢呼气6秒，重复几次\n2. **允许自己休息**：心态不好时，不要逼自己\"必须好起来\"\n3. **写下来**：把困扰你的事情写出来，有时候会帮助理清思绪\n\n---\n\n你愿意多说说发生了什么吗？我会在这里认真倾听。💛', 'text', 0, '2026-03-10 14:48:52', '{\"plan_suggestion\": {\"id\": \"doctor-sleep-review\", \"time\": \"21:00-21:15\", \"score\": 20, \"title\": \"睡眠记录回顾\", \"reason\": \"这轮对话集中在睡眠困扰，先补一晚记录最容易执行，也方便下次继续判断。\", \"source\": \"AI 心理医生建议\", \"priority\": \"关键\", \"description\": \"今晚记录入睡时间、夜间醒来次数和起床后的精神状态，下一次对话继续复盘。\"}}', 1, '2026-03-10 14:49:11', '2026-03-10 14:49:11', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (38, 29, 14, 'doctor', 'user', '你觉得我需要出去走走吗', 'text', 0, '2026-03-10 14:51:54', NULL, 1, '2026-03-10 14:51:54', '2026-03-10 14:51:54', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (39, 29, 14, 'doctor', 'assistant', '这是一个很好的问题，说明你在主动照顾自己，这本身就很棒。🌟\n\n**出去走走通常对心态有帮助**，原因包括：\n- 🌿 新鲜空气和自然光线可以调节情绪\n- 🚶 身体活动会促进内啡肽分泌，让人感觉轻松一些\n- 🔄 转换环境，有时候思绪也会跟着\"换个频道\"\n\n---\n\n**不过，我想先了解一下你现在的状态：**\n\n1. **身体上**：你觉得有体力出门吗？还是感觉很累、不想动？\n2. **情绪上**：现在愿意接触外面的环境吗？还是更想一个人待着？\n3. **安全上**：如果出门，你确定自己能安全回来吗？\n\n---\n\n**我的建议是：**\n\n✅ 如果你有一点体力，也愿意试试——哪怕只是下楼走5-10分钟、晒晒太阳，或者到附近的公园坐一坐，都可能让心情舒缓一些。\n\n✅ 如果现在真的很累、不想动——那待在家里休息也是完全可以的，照顾自己没有\"标准答案\"。\n\n---\n\n**你现在的感觉是怎样的呢？** 你可以告诉我更多，我们一起看看什么对你来说是最舒服的选择。💛', 'text', 0, '2026-03-10 14:51:54', '{\"plan_suggestion\": {\"id\": \"doctor-emotion-track\", \"time\": \"18:30-18:45\", \"score\": 15, \"title\": \"情绪波动追踪\", \"reason\": \"这次主要在谈情绪波动，先把触发场景记下来，比泛泛努力更容易持续。\", \"source\": \"AI 心理医生建议\", \"priority\": \"一般\", \"description\": \"用 15 分钟记录今天情绪起伏最明显的场景、身体感受和当时的应对动作。\"}}', 1, '2026-03-10 14:52:22', '2026-03-10 14:52:22', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (40, 31, 14, 'patient', 'user', '感觉很焦虑怎么办', 'text', 0, '2026-03-10 16:41:24', NULL, 1, '2026-03-10 16:41:24', '2026-03-10 16:41:24', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (41, 31, 14, 'patient', 'assistant', '我理解你现在的焦虑感受，焦虑是很常见的情绪体验。让我帮你梳理一下情况：\n\n## 首先，让我们一起了解你的焦虑：\n\n**1. 焦虑的具体表现**\n- 是持续性的担心还是突然发作？\n- 有身体症状吗？（如心跳加速、出汗、肌肉紧张、睡眠问题等）\n- 主要在什么情况下出现？\n\n**2. 可能的诱因**\n- 最近是否遇到压力事件？（工作、学习、人际关系等）\n- 有没有特定的触发场景？\n- 焦虑持续多长时间了？\n\n## 一些即时缓解方法：\n\n**呼吸放松**\n- 尝试4-7-8呼吸法：吸气4秒，屏息7秒，呼气8秒\n\n**身体放松**\n- 渐进式肌肉放松\n- 适度运动或散步\n\n**认知调整**\n- 问自己：\"这个担心是事实还是想象？\"\n- \"最坏的结果是什么？我能应对吗？\"\n\n**转移注意力**\n- 做一些需要专注的活动\n- 与信任的人交流\n\n## 何时需要专业帮助：\n- 焦虑严重影响日常生活\n- 伴有恐慌发作\n- 持续时间较长（超过2周）\n- 有回避行为\n\n你能告诉我更多关于你焦虑的具体情况吗？这样我可以给你更有针对性的建议。记住，寻求帮助是勇敢的表现，你并不孤单。', 'text', 0, '2026-03-10 16:41:24', '{\"plan_suggestion\": {\"id\": \"patient-soothing-rehearsal\", \"time\": \"18:00-18:20\", \"score\": 20, \"title\": \"安抚回应演练\", \"reason\": \"这轮对话强调了安抚和承接情绪，马上再演练一次最容易形成稳定表达。\", \"source\": \"AI 模拟病人建议\", \"priority\": \"关键\", \"description\": \"对照刚才的对话，用更平稳的语气再演练一遍安抚回应和情绪承接。\"}}', 1, '2026-03-10 16:41:41', '2026-03-10 16:41:41', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (42, 33, 14, 'doctor', 'user', '好想一直沉睡下去啊', 'text', 0, '2026-03-10 18:08:32', NULL, 0, '2026-03-10 18:08:32', '2026-03-10 18:41:49', '2026-03-10 18:41:49');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (43, 33, 14, 'doctor', 'assistant', '我听到你这样说，有些担心你。🫂\n\n这句话让我想多了解一些——你能跟我多说一点吗？是最近特别累、很疲惫，还是心里有什么让你觉得难以承受的事情？\n\n有时候我们会想\"沉睡下去\"，可能是：\n- 身体和精神都很疲惫，渴望真正的休息\n- 现实中有些事情让你感到无力或想逃避\n- 心里有些情绪不知道该怎么处理\n\n**我想确认一下你的安全：** 你说的\"沉睡\"，是指想要好好休息一下，还是有其他让你困扰的想法？\n\n如果你愿意，可以跟我说说最近发生了什么，或者你现在最需要的是什么。我会在这里听你说。💙\n\n---\n\n*如果你现在有任何想要伤害自己的念头，请告诉我，或者直接联系你信任的人、拨打心理援助热线（如北京心理援助热线：010-82951332，全国24小时希望热线：400-161-9995）。你不需要一个人扛着。*', 'text', 0, '2026-03-10 18:08:32', NULL, 0, '2026-03-10 18:08:51', '2026-03-10 18:41:49', '2026-03-10 18:41:49');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (44, 36, 14, 'doctor', 'user', '我有烦躁', 'text', 0, '2026-03-10 18:43:01', NULL, 0, '2026-03-10 18:43:01', '2026-03-10 18:44:21', '2026-03-10 18:44:21');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (45, 36, 14, 'doctor', 'assistant', '你好，感谢你愿意和我分享你的感受。烦躁是很常见的情绪体验，你愿意说出来已经是很好的第一步。🫂\n\n**我想先了解一下：**\n\n1. 这种烦躁感是最近才出现的，还是已经持续一段时间了？\n2. 有没有特别让你感到烦躁的事情或场景？比如工作、人际关系、睡眠问题等？\n3. 烦躁的时候，你的身体有什么感觉？比如心跳加快、坐立不安、胸闷等？\n\n---\n\n**在你准备回答之前，这里有一些可以尝试的小方法：**\n\n🌿 **即时缓解：**\n- 深呼吸练习：慢慢吸气4秒，屏住呼吸4秒，再慢慢呼气4秒，重复几次\n- 离开当前环境，到窗边或户外走走，呼吸新鲜空气\n- 用冷水洗把脸，或喝一杯温水\n\n📝 **梳理情绪：**\n- 把让你烦躁的事情写在纸上，写出来本身就是一种释放\n- 问自己：\"这件事我能控制吗？\"把可控和不可控的部分分开\n\n🚶 **适度运动：**\n- 散步10-15分钟，帮助身体释放紧张情绪\n\n---\n\n你不必着急回答所有问题，可以先说说最让你困扰的是什么，我们一起慢慢梳理。💙', 'text', 0, '2026-03-10 18:43:01', '{\"plan_suggestion\": {\"id\": \"doctor-sleep-review\", \"time\": \"21:00-21:15\", \"score\": 20, \"title\": \"睡眠记录回顾\", \"reason\": \"这轮对话集中在睡眠困扰，先补一晚记录最容易执行，也方便下次继续判断。\", \"source\": \"AI 心理医生建议\", \"priority\": \"关键\", \"description\": \"今晚记录入睡时间、夜间醒来次数和起床后的精神状态，下一次对话继续复盘。\"}}', 0, '2026-03-10 18:43:21', '2026-03-10 18:43:34', '2026-03-10 18:43:34');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (46, 36, 14, 'doctor', 'user', '真的快不行了', 'text', 0, '2026-03-10 18:43:47', NULL, 0, '2026-03-10 18:43:48', '2026-03-10 18:44:21', '2026-03-10 18:44:21');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (47, 36, 14, 'doctor', 'assistant', '我听到了你的痛苦，你能说出\"真的快不行了\"，说明你现在承受的压力和情绪已经很大了。谢谢你愿意表达出来，这需要勇气。🙏\n\n**我想先确认一下你的安全：**\n\n当你说\"快不行了\"的时候，你是指：\n- 情绪上特别难受、压抑、喘不过气？\n- 还是有想要伤害自己或结束生命的想法？\n\n**如果是后者，请你现在立刻：**\n- 联系身边的家人或朋友\n- 拨打心理援助热线：**全国心理援助热线 400-161-9995** 或 **北京危机干预热线 010-82951332**\n- 或直接前往最近医院的精神心理科/急诊\n\n---\n\n**如果你现在处于安全状态，只是情绪特别烦躁、崩溃，我想陪你一起梳理一下：**\n\n1. **先深呼吸几次** —— 慢慢吸气4秒，屏住2秒，慢慢呼气6秒，重复几次。这能帮助身体先平静一点。\n\n2. **发生了什么事让你这么烦躁？** 是工作、人际关系、还是说不清的情绪低落？可以说给我听听，我在这里陪着你。\n\n3. **这种感觉持续多久了？** 是今天突然的，还是已经有一段时间了？\n\n你不必一个人扛着，我会在这里听你说。💙', 'text', 0, '2026-03-10 18:43:47', '{\"plan_suggestion\": {\"id\": \"doctor-emotion-track\", \"time\": \"18:30-18:45\", \"score\": 15, \"title\": \"情绪波动追踪\", \"reason\": \"这次主要在谈情绪波动，先把触发场景记下来，比泛泛努力更容易持续。\", \"source\": \"AI 心理医生建议\", \"priority\": \"一般\", \"description\": \"用 15 分钟记录今天情绪起伏最明显的场景、身体感受和当时的应对动作。\"}}', 0, '2026-03-10 18:44:14', '2026-03-10 18:44:21', '2026-03-10 18:44:21');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (48, 37, 14, 'doctor', 'user', '你有什么好的资料抑郁症的建议', 'text', 0, '2026-03-10 18:54:31', NULL, 0, '2026-03-10 18:54:31', '2026-03-10 18:58:04', '2026-03-10 18:58:04');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (49, 37, 14, 'doctor', 'assistant', '你好，感谢你愿意分享你的困扰。我很理解寻求帮助需要勇气，你已经迈出了很重要的一步。\n\n## 关于抑郁症，我想先说明几点：\n\n**重要提醒**：抑郁症是一种需要专业诊断和治疗的心理健康问题，以下建议仅供参考，不能替代专业医生的诊断和治疗。\n\n## 一些可能有帮助的建议：\n\n### 🌱 **日常调节方面**\n- **规律作息**：尽量保持固定的睡眠和起床时间\n- **适度运动**：哪怕每天散步10-15分钟也有帮助\n- **阳光照射**：每天晒晒太阳，有助于调节情绪\n- **小目标设定**：将大任务分解成小步骤，逐步完成\n\n### 💬 **情绪表达方面**\n- **找人倾诉**：信任的家人、朋友或专业咨询师\n- **写日记**：记录自己的感受和想法\n- **不要自责**：抑郁症不是你的错，也不是软弱的表现\n\n### 🎯 **专业帮助方面**\n- **心理咨询**：寻求专业心理咨询师的帮助\n- **精神科就诊**：如果症状持续2周以上，建议到精神心理科就诊\n- **药物治疗**：在医生指导下，药物治疗可能很有帮助\n\n## ⚠️ **需要立即寻求帮助的情况**\n\n如果你或你身边的人出现以下情况，请**立即联系家属或专业机构**：\n- 有自伤或自杀的想法\n- 情绪极度低落，无法正常生活\n- 出现幻觉或严重焦虑\n- 感到绝望、失控\n\n**紧急求助电话**：\n- 全国心理援助热线：400-161-9995\n- 北京危机干预热线：010-82951332\n- 各地120急救电话\n\n---\n\n你现在感觉怎么样？有没有特别困扰你的方面？如果你愿意，可以和我说说你的具体情况，我会尽力提供更针对性的建议。记住，寻求帮助是勇敢的表现，你并不孤单。', 'text', 0, '2026-03-10 18:54:31', '{\"plan_suggestion\": {\"id\": \"doctor-sleep-review\", \"time\": \"21:00-21:15\", \"score\": 20, \"title\": \"睡眠记录回顾\", \"reason\": \"这轮对话集中在睡眠困扰，先补一晚记录最容易执行，也方便下次继续判断。\", \"source\": \"AI 心理医生建议\", \"priority\": \"关键\", \"description\": \"今晚记录入睡时间、夜间醒来次数和起床后的精神状态，下一次对话继续复盘。\"}}', 0, '2026-03-10 18:54:52', '2026-03-10 18:58:04', '2026-03-10 18:58:04');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (50, 37, 14, 'doctor', 'user', '我吃不下饭', 'text', 0, '2026-03-10 18:55:33', NULL, 0, '2026-03-10 18:55:34', '2026-03-10 18:58:04', '2026-03-10 18:58:04');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (51, 37, 14, 'doctor', 'assistant', '听到你这样说，我很担心你。**食欲下降、吃不下饭**确实是很多人在情绪低落时会遇到的问题，这种感受我能理解。\n\n## 🤗 先让我了解一下你的情况：\n\n**请问这种情况持续多久了？**\n- 是最近几天，还是已经有一段时间了？\n\n**现在的身体状况如何？**\n- 有没有头晕、乏力、胃痛等不适？\n- 体重有没有明显下降？\n\n## 💡 一些可能帮到你的建议：\n\n### 🍵 **短期应对方法**\n- **少食多餐**：不必强求三餐，能吃一点是一点\n- **选择易消化的食物**：粥、汤、面条、酸奶等\n- **流质食物**：牛奶、豆浆、果汁也可以补充营养\n- **不要强迫自己**：吃不下时不要自责，能吃多少是多少\n\n### 🌿 **改善食欲的小方法**\n- **适量运动**：散步可能会增加食欲\n- **换个环境吃饭**：去户外或换个房间\n- **和家人朋友一起吃**：有人陪伴可能会好一些\n\n## ⚠️ **需要重视的情况**\n\n如果你出现以下情况，**建议尽快就医**：\n- 已经**连续几天几乎没吃东西**\n- **体重明显下降**（一周内下降2-3斤以上）\n- 有**恶心、呕吐**等症状\n- 感到**极度虚弱、头晕眼花**\n\n---\n\n**你现在愿意告诉我：**\n- 这个症状持续多久了？\n- 今天吃了什么吗？\n- 还有其他身体不适吗？\n\n如果情况比较严重，我建议你告诉家人或朋友，让他们陪你去医院检查一下。**身体和情绪都需要照顾，这不是你一个人的事。**\n\n你愿意和我多说一些吗？我会一直在这里听你说。', 'text', 0, '2026-03-10 18:55:33', '{\"plan_suggestion\": {\"id\": \"doctor-emotion-track\", \"time\": \"18:30-18:45\", \"score\": 15, \"title\": \"情绪波动追踪\", \"reason\": \"这次主要在谈情绪波动，先把触发场景记下来，比泛泛努力更容易持续。\", \"source\": \"AI 心理医生建议\", \"priority\": \"一般\", \"description\": \"用 15 分钟记录今天情绪起伏最明显的场景、身体感受和当时的应对动作。\"}}', 0, '2026-03-10 18:55:55', '2026-03-10 18:58:04', '2026-03-10 18:58:04');
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (52, 37, 14, 'doctor', 'user', '啊，我好烦啊，好烦。', 'voice', 0, '2026-03-10 19:05:07', '{\"suffix\": \"webm\", \"audio_url\": \"http://10.0.0.9:8787/storage/20260310/e9804198885dbcda85353211937a89615a89a5da.webm\", \"mime_type\": \"audio/webm;codecs=opus\", \"size_byte\": 70814, \"transcript\": \"啊，我好烦啊，好烦。\", \"object_name\": \"e9804198885dbcda85353211937a89615a89a5da.webm\", \"storage_path\": \"public/storage/20260310/e9804198885dbcda85353211937a89615a89a5da.webm\", \"duration_label\": \"5\'\'\", \"duration_seconds\": 5}', 1, '2026-03-10 19:05:08', '2026-03-10 19:05:08', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (53, 37, 14, 'doctor', 'assistant', '你好呀，我能感受到你现在心情很烦躁。这种\"烦\"的感觉确实让人很难受，像是心里堵着什么似的。\n\n能跟我说说，是什么事情让你这么烦躁吗？是工作、学习、人际关系，还是一些说不清道不明的感觉呢？\n\n有时候，当我们把心里的烦躁说出来，哪怕只是简单地描述一下，心情也会稍微轻松一点点。我在这里听着，你可以慢慢说。🌿\n\n---\n\n**小贴士**：烦躁是很正常的情绪，每个人都会经历。你愿意主动表达出来，已经是很好的自我觉察了。', 'text', 0, '2026-03-10 19:05:07', NULL, 1, '2026-03-10 19:05:30', '2026-03-10 19:05:30', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (54, 38, 14, 'doctor', 'user', '我好累啊', 'text', 0, '2026-03-10 21:24:38', NULL, 1, '2026-03-10 21:24:39', '2026-03-10 21:24:39', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (55, 38, 14, 'doctor', 'assistant', '你好呀，我听到了你的声音。**\"累\"这种感觉，真的很不容易**。谢谢你愿意说出来。\n\n---\n\n**先让我陪着你，深呼吸一下：**\n- 慢慢吸气……\n- 再慢慢呼出来……\n\n---\n\n我想更好地理解你，如果可以的话，能跟我多说一点吗？\n\n比如：\n- 🌙 是身体上的疲惫？（比如睡眠不好、体力透支）\n- 💭 还是心里的累？（比如压力大、情绪低落、觉得没意义）\n- 🕐 是最近才这样，还是已经持续一段时间了？\n- 🏠 身边有人可以聊聊吗？\n\n---\n\n**你现在最需要的是休息，还是想找人说说话？**我都愿意听。\n\n你可以慢慢说，不用着急。💛', 'text', 0, '2026-03-10 21:24:38', NULL, 1, '2026-03-10 21:24:53', '2026-03-10 21:24:53', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (56, 38, 14, 'doctor', 'user', '好累好累，真的好累好累。', 'voice', 0, '2026-03-10 21:25:55', '{\"suffix\": \"mp4\", \"audio_url\": \"http://10.0.0.9:8787/storage/20260310/0db1865fd99f0530c73cd23fc02ce7ff87c038b3.mp4\", \"mime_type\": \"audio/mp4\", \"size_byte\": 95507, \"transcript\": \"好累好累，真的好累好累。\", \"object_name\": \"0db1865fd99f0530c73cd23fc02ce7ff87c038b3.mp4\", \"storage_path\": \"public/storage/20260310/0db1865fd99f0530c73cd23fc02ce7ff87c038b3.mp4\", \"duration_label\": \"6\'\'\", \"duration_seconds\": 6}', 1, '2026-03-10 21:25:56', '2026-03-10 21:25:56', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (57, 38, 14, 'doctor', 'assistant', '我听到了。\n\n**真的好累好累，对吗？**\n\n那种累，可能不是睡一觉就能好的。\n\n---\n\n**我就在这里，你不用一个人扛着。**\n\n---\n\n如果你想哭，可以哭一会儿。\n如果你想发呆，就发呆一会儿。\n如果你想说什么，我都在听。\n\n---\n\n**我想轻轻问你：**\n\n你现在……安全吗？身边有人吗？\n\n如果觉得撑不住了，或者有任何伤害自己的念头，请一定要告诉我，或者找身边信任的人说一声，好吗？\n\n---\n\n你不必现在就想\"怎么办\"，也不必马上好起来。\n\n**此时此刻，能说出来，已经很勇敢了。** 💛\n\n我陪着你。', 'text', 0, '2026-03-10 21:25:55', NULL, 1, '2026-03-10 21:26:09', '2026-03-10 21:26:09', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (58, 50, 15, 'doctor', 'user', 'The对吗？', 'voice', 0, '2026-03-11 11:53:31', '{\"suffix\": \"mp4\", \"audio_url\": \"http://10.0.0.9:8787/storage/20260311/40c6329a8a70bec2abb589ba9747a0751e8d4075.mp4\", \"mime_type\": \"audio/mp4\", \"size_byte\": 100342, \"transcript\": \"The对吗？\", \"object_name\": \"40c6329a8a70bec2abb589ba9747a0751e8d4075.mp4\", \"storage_path\": \"public/storage/20260311/40c6329a8a70bec2abb589ba9747a0751e8d4075.mp4\", \"duration_label\": \"7\'\'\", \"duration_seconds\": 7}', 1, '2026-03-11 11:53:31', '2026-03-11 11:53:31', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (59, 50, 15, 'doctor', 'assistant', '您好！我注意到您的消息似乎不太完整——\"The对吗？\"这句话让我有点困惑。\n\n您是想：\n- 询问某个说法或想法是否正确？\n- 确认某件事是否\"对\"或\"合适\"？\n- 还是在表达其他困扰？\n\n请您补充完整，我会认真倾听并尽力帮助您。😊\n\n如果您感到焦虑或不确定，可以慢慢说，我会在这里陪着您。您愿意多告诉我一些吗？您好！我注意到您的问题似乎不太完整——\"The对吗？\"\n\n您是想问关于英语语法中\"The\"的用法是否正确吗？还是想问其他问题？\n\n请您补充完整您的问题，我会尽力帮助您解答。如果您是在学习英语或对某个句子有疑问，可以告诉我完整的句子，我可以帮您分析是否正确使用。😊', 'text', 0, '2026-03-11 11:53:31', NULL, 1, '2026-03-11 11:53:52', '2026-03-11 11:53:52', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (60, 53, 14, 'doctor', 'user', '焦虑要如何缓解', 'text', 0, '2026-03-14 18:47:02', NULL, 1, '2026-03-14 18:47:03', '2026-03-14 18:47:03', NULL);
INSERT INTO `sa_member_chat_record` (`id`, `session_id`, `member_id`, `chat_mode`, `role`, `content`, `content_type`, `token_count`, `message_time`, `ext`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (61, 53, 14, 'doctor', 'assistant', '您好，感谢您的信任。焦虑是很常见的情绪体验，很多人都会遇到。我想先了解一下您的情况，以便给您更有针对性的建议。\n\n**首先，我想澄清几个问题：**\n- 您的焦虑是偶尔出现，还是持续一段时间了？\n- 是对特定事情感到焦虑，还是说不清原因的焦虑？\n- 这种焦虑是否影响了您的睡眠、工作或日常生活？\n\n---\n\n**在您回答之前，我可以先分享一些通用的缓解焦虑的方法：**\n\n### 🌿 即时缓解技巧\n1. **深呼吸法**：尝试\"4-7-8\"呼吸法——吸气4秒，屏息7秒，呼气8秒，重复几次\n2. **接地练习**：说出5个你能看到的东西、4个你能触摸的东西、3个你能听到的声音\n3. **肌肉放松**：从头到脚依次紧绷再放松各部位肌肉\n\n### 📝 日常调节建议\n1. **规律作息**：保持充足睡眠，尽量固定作息时间\n2. **适度运动**：散步、瑜伽、慢跑等都能帮助释放压力\n3. **减少刺激**：限制咖啡因摄入，睡前减少手机使用\n4. **写情绪日记**：把担忧的事情写下来，有助于理清思绪\n\n### 💭 认知调整\n- 问问自己：\"这件事最坏的结果是什么？我能接受吗？\"\n- 把\"万一\"变成\"即使……我也可以……\"\n\n---\n\n**温馨提示：**\n以上建议仅供参考，不能替代专业诊断。如果您感到焦虑持续时间较长、严重影响生活，或伴有心慌、胸闷、失眠等明显躯体症状，建议您前往线下精神心理科或心理咨询机构寻求专业帮助。\n\n您愿意多说说您的具体情况吗？我会尽力帮您分析。💛', 'text', 0, '2026-03-14 18:47:02', '{\"plan_suggestion\": {\"id\": \"doctor-sleep-review\", \"time\": \"21:00-21:15\", \"score\": 20, \"title\": \"睡眠记录回顾\", \"reason\": \"这轮对话集中在睡眠困扰，先补一晚记录最容易执行，也方便下次继续判断。\", \"source\": \"AI 心理医生建议\", \"priority\": \"关键\", \"description\": \"今晚记录入睡时间、夜间醒来次数和起床后的精神状态，下一次对话继续复盘。\"}}', 1, '2026-03-14 18:47:20', '2026-03-14 18:47:20', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (1, 5, 'doctor', '第一次访问', '我们先一起梳理今天的高风险触发点。', '2026-03-06 19:47:08', 1, 1, '2026-03-06 19:47:08', '2026-03-06 19:47:08', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (2, 5, 'companion', '晚间复盘', '你已经完成替代行为，这很关键。', '2026-03-06 18:47:08', 0, 1, '2026-03-06 19:47:08', '2026-03-06 19:47:08', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (6, 11, 'doctor', '你好', '你好呀，很高兴见到你。😊\n\n我是你的心理医生助手，在这里随时准备倾听你的心声。无论你今天是想聊聊最近的烦恼、困惑，还是只是想找个人说说话，我都在这里陪着你。\n\n你今天过得怎么样？有什么想和我分享的吗？', '2026-03-09 19:11:37', 0, 1, '2026-03-09 19:11:37', '2026-03-09 19:11:37', NULL);
