INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (8, 11, 'doctor', '第3次对话', NULL, '2026-03-09 19:29:26', 0, 1, '2026-03-09 19:29:26', '2026-03-09 19:29:26', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (9, 14, 'doctor', '第1次对话', '你好！很高兴见到你。😊\n\n我是你的AI心理医生助手，在这里陪伴你、倾听你的心声。无论你是遇到了一些困扰，还是只是想找人聊聊，我都很愿意倾听。\n\n今天感觉怎么样？有什么想和我分享的吗？我会认真倾听，尽我所能给你支持和建议。', '2026-03-09 20:59:40', 0, 1, '2026-03-09 20:59:31', '2026-03-09 20:59:41', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (10, 9, 'doctor', '第1次对话', '没关系，慢慢来～ 😊\n\n我感觉到你可能在思考，或者一时不知道从哪里说起，这完全正常。\n\n**不如我们先从最简单的开始？**\n\n你可以告诉我：\n- 🌤️ 你现在的心情怎么样？（比如：有点累、有点烦、还好、说不清...）\n- 🕐 最近有什么事让', '2026-03-09 23:04:29', 0, 1, '2026-03-09 22:12:31', '2026-03-09 23:04:43', NULL);
