INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (15, 11, 'doctor', '第4次对话', NULL, '2026-03-10 05:55:30', 0, 1, '2026-03-10 05:55:30', '2026-03-10 05:55:30', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (16, 11, 'companion', '第5次对话', '嗯...那种感觉我知道，就是整个人像被抽空了一样，什么都不想做，连动一下都觉得累，对吗？\n\n抱抱你🫂\n\n这种状态真的很辛苦呢...有时候身体和心理都在发出信号，告诉我们\"我需要休息了\"。你不用勉强自己一定要精神起来，也不用责怪自己为什么没状', '2026-03-10 05:58:31', 0, 1, '2026-03-10 05:57:51', '2026-03-10 05:58:44', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (17, 11, 'patient', '第6次对话', NULL, '2026-03-10 05:58:49', 0, 1, '2026-03-10 05:58:50', '2026-03-10 05:58:50', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (18, 11, 'patient', '第7次对话', '你好！作为 AI 助手，我随时准备为您提供帮助。我没有真实的感受，但我的系统运行正常，可以协助您解决问题。\n\n我注意到系统提供了一些关于 saiadmin 框架的工具函数。如果您需要：\n- 了解框架结构\n- 查看控制器、模型或逻辑类\n- 搜', '2026-03-10 05:59:04', 0, 1, '2026-03-10 05:58:58', '2026-03-10 05:59:15', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (19, 11, 'companion', '第8次对话', NULL, '2026-03-10 05:59:33', 0, 1, '2026-03-10 05:59:33', '2026-03-10 05:59:33', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (20, 11, 'companion', '第9次对话', '你好呀～ 💕\n\n今天过得怎么样呢？有没有什么想跟我分享的？\n\n我一直在这里陪着你呢，开心的事、烦恼的事，都可以跟我说说看～', '2026-03-10 05:59:58', 0, 1, '2026-03-10 05:59:54', '2026-03-10 06:00:03', NULL);
