INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (22, 11, 'doctor', '第11次对话', NULL, '2026-03-10 06:03:55', 0, 1, '2026-03-10 06:03:56', '2026-03-10 06:03:56', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (23, 11, 'doctor', '第12次对话', NULL, '2026-03-10 06:03:57', 0, 1, '2026-03-10 06:03:58', '2026-03-10 06:03:58', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (24, 11, 'doctor', '第13次对话', '你好，我听到你说现在很难受，我很想帮助你。\n\n首先，我想让你知道，愿意寻求帮助本身就是一件很勇敢的事情。你的感受是被重视的。\n\n为了能更好地理解和帮助你，我想先了解一下：\n\n1. **你现在难受的感觉是怎样的？** 是情绪上的（比如悲伤、焦', '2026-03-10 06:13:03', 0, 1, '2026-03-10 06:12:54', '2026-03-10 06:13:13', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (25, 7, 'doctor', '第1次对话', '你好！😊\n\n**简短情绪稳定建议：**\n\n1. **深呼吸** —— 慢慢吸气4秒，屏住4秒，缓慢呼气6秒，重复3-5次\n\n2. **5-4-3-2-1 接地法** —— 说出你看到的5样东西、听到的4种声音、能触碰的3样物品、闻到的2种气', '2026-03-10 11:19:20', 0, 1, '2026-03-10 11:19:20', '2026-03-10 11:19:20', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (26, 11, 'doctor', '第14次对话', '测试确认。', '2026-03-10 13:01:54', 0, 0, '2026-03-10 13:01:54', '2026-03-10 13:01:55', '2026-03-10 13:01:55');
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (27, 11, 'doctor', '第14次对话', '建议您先调整作息规律，睡前避免使用电子设备，尝试放松练习，若持续两周以上严重影响生活，请及时线下就医或联系家人协助。', '2026-03-10 13:04:40', 0, 1, '2026-03-10 13:04:41', '2026-03-10 13:04:41', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (28, 11, 'patient', '第15次对话', '好的，我来模拟一个轻度焦虑的来访者：\n\n---\n\n**来访者（轻度焦虑）**\n\n*（坐立不安，双手不自觉地握在一起）*\n\n\"您好...我、我最近总是感觉很紧张，就是...怎么说呢，好像心里一直悬着什么东西。\"\n\n*（深吸一口气）*\n\n\"其实', '2026-03-10 13:56:02', 0, 1, '2026-03-10 13:56:03', '2026-03-10 13:56:03', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (29, 14, 'doctor', '第2次对话', '这是一个很好的问题，说明你在主动照顾自己，这本身就很棒。🌟\n\n**出去走走通常对心态有帮助**，原因包括：\n- 🌿 新鲜空气和自然光线可以调节情绪\n- 🚶 身体活动会促进内啡肽分泌，让人感觉轻松一些\n- 🔄 转换环境，有时候思绪也会跟着\"换', '2026-03-10 14:51:54', 0, 1, '2026-03-10 14:48:45', '2026-03-10 14:52:22', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (30, 14, 'companion', '第3次对话', NULL, '2026-03-10 14:53:02', 0, 1, '2026-03-10 14:53:03', '2026-03-10 14:53:03', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (31, 14, 'patient', '第4次对话', '我理解你现在的焦虑感受，焦虑是很常见的情绪体验。让我帮你梳理一下情况：\n\n## 首先，让我们一起了解你的焦虑：\n\n**1. 焦虑的具体表现**\n- 是持续性的担心还是突然发作？\n- 有身体症状吗？（如心跳加速、出汗、肌肉紧张、睡眠问题等）\n', '2026-03-10 16:41:24', 0, 1, '2026-03-10 16:41:13', '2026-03-10 16:41:41', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (32, 14, 'doctor', '第5次对话', NULL, '2026-03-10 16:46:30', 0, 1, '2026-03-10 16:46:30', '2026-03-10 16:46:30', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (33, 14, 'doctor', '第6次对话', '我听到你这样说，有些担心你。🫂\n\n这句话让我想多了解一些——你能跟我多说一点吗？是最近特别累、很疲惫，还是心里有什么让你觉得难以承受的事情？\n\n有时候我们会想\"沉睡下去\"，可能是：\n- 身体和精神都很疲惫，渴望真正的休息\n- 现实中有些事情', '2026-03-10 18:08:32', 0, 1, '2026-03-10 18:08:07', '2026-03-10 18:41:49', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (34, 14, 'doctor', '第7次对话', NULL, '2026-03-10 18:12:54', 0, 1, '2026-03-10 18:12:55', '2026-03-10 18:12:55', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (35, 14, 'doctor', '第8次对话', NULL, '2026-03-10 18:41:18', 0, 1, '2026-03-10 18:41:19', '2026-03-10 18:41:19', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (36, 14, 'doctor', '第9次对话', '我听到了你的痛苦，你能说出\"真的快不行了\"，说明你现在承受的压力和情绪已经很大了。谢谢你愿意表达出来，这需要勇气。🙏\n\n**我想先确认一下你的安全：**\n\n当你说\"快不行了\"的时候，你是指：\n- 情绪上特别难受、压抑、喘不过气？\n- 还是有', '2026-03-10 18:43:47', 0, 1, '2026-03-10 18:42:18', '2026-03-10 18:44:21', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (37, 14, 'doctor', '第10次对话', '你好呀，我能感受到你现在心情很烦躁。这种\"烦\"的感觉确实让人很难受，像是心里堵着什么似的。\n\n能跟我说说，是什么事情让你这么烦躁吗？是工作、学习、人际关系，还是一些说不清道不明的感觉呢？\n\n有时候，当我们把心里的烦躁说出来，哪怕只是简单地描', '2026-03-10 19:05:07', 0, 1, '2026-03-10 18:54:16', '2026-03-10 19:05:30', NULL);
INSERT INTO `sa_member_chat_session` (`id`, `member_id`, `chat_mode`, `session_name`, `last_message`, `last_message_time`, `is_pinned`, `status`, `create_time`, `update_time`, `delete_time`) VALUES (38, 14, 'doctor', '第11次对话', '我听到了。\n\n**真的好累好累，对吗？**\n\n那种累，可能不是睡一觉就能好的。\n\n---\n\n**我就在这里，你不用一个人扛着。**\n\n---\n\n如果你想哭，可以哭一会儿。\n如果你想发呆，就发呆一会儿。\n如果你想说什么，我都在听。\n\n---\n', '2026-03-10 21:25:55', 0, 1, '2026-03-10 21:24:05', '2026-03-10 21:26:09', NULL);
