-- ----------------------------
-- Table structure for sa_article
-- ----------------------------
DROP TABLE IF EXISTS `sa_article`;
CREATE TABLE `sa_article` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '编号',
  `category_id` int NOT NULL COMMENT '分类id',
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文章标题',
  `author` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文章作者',
  `image` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '文章图片',
  `describe` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章简介',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '文章内容',
  `views` int DEFAULT '0' COMMENT '浏览次数',
  `sort` int unsigned DEFAULT '100' COMMENT '排序',
  `status` tinyint unsigned DEFAULT '1' COMMENT '状态',
  `is_link` tinyint(1) DEFAULT '2' COMMENT '是否外链',
  `link_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '链接地址',
  `is_hot` tinyint unsigned DEFAULT '2' COMMENT '是否热门',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='文章表';

-- ----------------------------
-- Records of sa_article
-- ----------------------------
BEGIN;
COMMIT;

