-- ----------------------------
-- Table structure for sa_daily_task
-- ----------------------------
DROP TABLE IF EXISTS `sa_daily_task`;
CREATE TABLE `sa_daily_task` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '患者ID',
  `stage_id` int NOT NULL DEFAULT '0' COMMENT '所属阶段ID(若有关联阶段)',
  `task_date` date NOT NULL COMMENT '任务具体日期',
  `start_time` time DEFAULT NULL COMMENT '任务开始时间（可选小时分钟）',
  `end_time` time DEFAULT NULL COMMENT '任务结束时间',
  `title` varchar(100) NOT NULL COMMENT '关键任务标题',
  `description` text COMMENT '任务描述/详情',
  `reminders` json DEFAULT NULL COMMENT '提醒配置规则例如:["T-30m", "on-time"]',
  `source` varchar(20) NOT NULL DEFAULT 'timeline' COMMENT '任务来源：chat=AI对话生成, timeline=阶段计划自带, manual=手动创建',
  `points_reward` int NOT NULL DEFAULT '10' COMMENT '完成一次的奖励分数',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待办, 1=已完成, 2=已跳过, 3=已延期',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_member_date` (`member_id`,`task_date`),
  KEY `idx_stage_date` (`stage_id`,`task_date`),
  KEY `idx_member_status` (`member_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日时间线任务表';

