-- ----------------------------
-- Table structure for sa_member
-- ----------------------------
DROP TABLE IF EXISTS `sa_member`;
CREATE TABLE `sa_member` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '会员ID',
  `username` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户名',
  `nickname` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头像',
  `mobile` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `password_hash` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密码哈希',
  `role` tinyint(1) NOT NULL DEFAULT '1' COMMENT '角色：1=患者, 2=医生',
  `certification_images` json DEFAULT NULL COMMENT '资格证书图片URL数组',
  `certification_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核状态：0=待审核, 1=已通过, 2=已拒绝',
  `certification_remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核备注',
  `gender` tinyint(1) NOT NULL DEFAULT '0' COMMENT '性别：0=未设置, 1=男, 2=女',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `age_range` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '年龄段：如18-25, 26-35',
  `bio` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '个人简介',
  `baseline_frequency` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用药基线-频率（可选）',
  `baseline_dosage` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用药基线-量级（可选）',
  `triggers` json DEFAULT NULL COMMENT '触发因素JSON数组',
  `recovery_goal` tinyint(1) NOT NULL DEFAULT '0' COMMENT '康复目标：0=未设置, 1=完全戒断, 2=减少使用',
  `community_visibility` tinyint(1) NOT NULL DEFAULT '1' COMMENT '社区可见范围：1=公开, 2=半公开, 3=匿名',
  `journal_ai_access` tinyint(1) NOT NULL DEFAULT '1' COMMENT '日记AI摘要权限：1=允许, 0=禁止',
  `agreed_terms_at` datetime DEFAULT NULL COMMENT '同意隐私条款时间',
  `member_level_id` int NOT NULL DEFAULT '1' COMMENT '会员等级ID',
  `points_balance` int NOT NULL DEFAULT '0' COMMENT '当前积分余额',
  `last_login_ip` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最后登录IP',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `register_platform_id` tinyint DEFAULT NULL COMMENT '注册平台',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-正常，2-冻结，3-注销',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_member_username` (`username`),
  UNIQUE KEY `uk_member_email` (`email`),
  KEY `idx_mobile` (`mobile`) USING BTREE,
  KEY `idx_role_status` (`role`,`status`),
  KEY `idx_certification_status` (`certification_status`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员基础信息表';

-- ----------------------------
-- Records of sa_member
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_member_assessment_result
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_assessment_result`;
CREATE TABLE `sa_member_assessment_result` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '患者ID',
  `doctor_id` int NOT NULL DEFAULT '0' COMMENT '医生ID',
  `task_id` int NOT NULL COMMENT '关联任务ID',
  `assessment_id` varchar(64) DEFAULT NULL COMMENT '量表ID',
  `assessment_title` varchar(100) NOT NULL COMMENT '量表名称',
  `task_title` varchar(100) NOT NULL COMMENT '任务标题',
  `stage_key` varchar(20) DEFAULT NULL COMMENT '阶段标识',
  `question_count` int NOT NULL DEFAULT '0' COMMENT '题目数',
  `total_score` int NOT NULL DEFAULT '0' COMMENT '总分',
  `achieved_score` int NOT NULL DEFAULT '0' COMMENT '实得分',
  `answers` json DEFAULT NULL COMMENT '作答结果JSON',
  `assessment_snapshot` json DEFAULT NULL COMMENT '量表快照JSON',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_member_task` (`member_id`,`task_id`),
  KEY `idx_doctor_member` (`doctor_id`,`member_id`),
  KEY `idx_member_create_time` (`member_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员量表提交结果表';

-- ----------------------------
-- Records of sa_member_assessment_result
-- ----------------------------
BEGIN;
COMMIT;

