COMMIT;

-- ----------------------------
-- Table structure for sa_member_memoir
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_memoir`;
CREATE TABLE `sa_member_memoir` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '会员ID',
  `grant_level_id` int NOT NULL DEFAULT '0' COMMENT '解锁等级ID',
  `grant_level_rank` int NOT NULL DEFAULT '0' COMMENT '解锁等级序号',
  `grant_level_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '解锁等级名称',
  `title` varchar(120) COLLATE utf8mb4_general_ci NOT NULL COMMENT '回忆录标题',
  `description` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '回忆录描述',
  `cover` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面图',
  `video_url` varchar(500) COLLATE utf8mb4_general_ci NOT NULL COMMENT '视频地址',
  `source_month` varchar(7) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '来源月份',
  `journal_count` int NOT NULL DEFAULT '0' COMMENT '日记数量',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=正常,2=隐藏',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_member_level_rank` (`member_id`,`grant_level_rank`) USING BTREE,
  KEY `idx_member_status` (`member_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员专属回忆录表';

-- ----------------------------
-- Table structure for sa_member_level
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_level`;
CREATE TABLE `sa_member_level` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `level_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '等级名称：如普通会员、白银、黄金',
  `level_code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '等级标识：如NORMAL、SILVER、GOLD',
  `min_points` int NOT NULL DEFAULT '0' COMMENT '升级所需最低积分',
  `max_points` int DEFAULT NULL COMMENT '等级上限积分（null表示无上限）',
  `level_icon` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '等级图标URL（多平台通用）',
  `privileges` text COLLATE utf8mb4_general_ci COMMENT '等级权益（JSON格式，如{"discount":0.9,"free_shipping":true}）',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_level_code` (`level_code`) USING BTREE,
  KEY `idx_min_points` (`min_points`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员等级表';

-- ----------------------------
-- Records of sa_member_level
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_member_login_log
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_login_log`;
CREATE TABLE `sa_member_login_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `member_id` bigint NOT NULL COMMENT '会员ID（关联member表）',
  `platform_id` tinyint NOT NULL COMMENT '登录平台ID（关联member_platform表）',
  `login_type` tinyint DEFAULT NULL COMMENT '登录方式',
  `login_ip` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录IP',
  `login_location` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录地点（通过IP解析）',
  `user_agent` text COLLATE utf8mb4_general_ci COMMENT '用户代理（浏览器/设备信息）',
  `login_result` tinyint DEFAULT NULL COMMENT '登录结果：1-成功，0-失败',
  `fail_reason` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '失败原因（如密码错误、账号冻结）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_member_id` (`member_id`) USING BTREE,
  KEY `idx_platform_time` (`platform_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=259 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员登录日志表';

-- ----------------------------
-- Records of sa_member_login_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_member_message
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_message`;
CREATE TABLE `sa_member_message` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '接收会员ID',
  `message_type` tinyint(1) NOT NULL COMMENT '消息类型:1关注 2回复 3任务 4预约',
  `title` varchar(100) NOT NULL COMMENT '消息标题',
  `content` varchar(500) NOT NULL COMMENT '消息内容',
  `device_token` varchar(255) DEFAULT NULL COMMENT '设备推送token',
  `is_pushed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已推送:0未推送,1已推送',
  `push_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '推送状态:0待推送,1成功,2失败',
  `push_time` datetime DEFAULT NULL COMMENT '推送完成时间',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读:0未读,1已读',
  `read_time` datetime DEFAULT NULL COMMENT '已读时间',
  `biz_type` varchar(50) DEFAULT NULL COMMENT '业务类型',
  `biz_id` int DEFAULT '0' COMMENT '业务ID',
  `ext` json DEFAULT NULL COMMENT '扩展信息',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态:1有效,2禁用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_member_read_status` (`member_id`,`is_read`,`status`),
  KEY `idx_member_type` (`member_id`,`message_type`),
  KEY `idx_member_push_status` (`member_id`,`is_pushed`,`push_status`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员消息中心表';

-- ----------------------------
-- Records of sa_member_message
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_member_platform
-- ----------------------------
DROP TABLE IF EXISTS `sa_member_platform`;
CREATE TABLE `sa_member_platform` (
  `id` tinyint NOT NULL AUTO_INCREMENT COMMENT '平台ID',
  `platform_name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台名称：PC、小程序、公众号、H5、钉钉、企业微信',
  `platform_code` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台唯一标识：如PC-WEB、MINI-PROGRAM、WECHAT-OFFICIAL、H5、DINGTALK、WEWORK',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_platform_code` (`platform_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='多平台配置表';

