  `site_desc` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '站点描述',
  `site_keywords` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '站点关键词',
  `site_copyright` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版权信息',
  `site_record_number` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备案号',
  `site_config` text COLLATE utf8mb4_general_ci COMMENT '站点配置',
