-- ----------------------------
-- Table structure for sa_tool_crontab
-- ----------------------------
DROP TABLE IF EXISTS `sa_tool_crontab`;
CREATE TABLE `sa_tool_crontab` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务名称',
  `type` smallint DEFAULT '4' COMMENT '任务类型',
  `target` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '调用任务字符串',
  `parameter` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '调用任务参数',
  `task_style` tinyint(1) DEFAULT NULL COMMENT '执行类型',
  `rule` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务执行表达式',
  `singleton` smallint DEFAULT '1' COMMENT '是否单次执行 (1 是 2 不是)',
  `status` smallint DEFAULT '1' COMMENT '状态 (1正常 2停用)',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='定时任务信息表';

-- ----------------------------
-- Records of sa_tool_crontab
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_tool_crontab_log
-- ----------------------------
DROP TABLE IF EXISTS `sa_tool_crontab_log`;
CREATE TABLE `sa_tool_crontab_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `crontab_id` int unsigned DEFAULT NULL COMMENT '任务ID',
  `name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务名称',
  `target` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务调用目标字符串',
  `parameter` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务调用参数',
  `exception_info` varchar(2000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '异常信息',
  `status` smallint DEFAULT '1' COMMENT '执行状态 (1成功 2失败)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='定时任务执行日志表';

-- ----------------------------
-- Records of sa_tool_crontab_log
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_tool_generate_columns
-- ----------------------------
DROP TABLE IF EXISTS `sa_tool_generate_columns`;
CREATE TABLE `sa_tool_generate_columns` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `table_id` int unsigned DEFAULT NULL COMMENT '所属表ID',
  `column_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字段名称',
  `column_comment` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字段注释',
  `column_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字段类型',
  `default_value` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认值',
  `is_pk` smallint DEFAULT '1' COMMENT '1 非主键 2 主键',
  `is_required` smallint DEFAULT '1' COMMENT '1 非必填 2 必填',
  `is_insert` smallint DEFAULT '1' COMMENT '1 非插入字段 2 插入字段',
  `is_edit` smallint DEFAULT '1' COMMENT '1 非编辑字段 2 编辑字段',
  `is_list` smallint DEFAULT '1' COMMENT '1 非列表显示字段 2 列表显示字段',
  `is_query` smallint DEFAULT '1' COMMENT '1 非查询字段 2 查询字段',
  `is_sort` smallint DEFAULT '1' COMMENT '1 非排序 2 排序',
  `query_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'eq' COMMENT '查询方式 eq 等于, neq 不等于, gt 大于, lt 小于, like 范围',
  `view_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'text' COMMENT '页面控件,text, textarea, password, select, checkbox, radio, date, upload, ma-upload(封装的上传控件)',
  `dict_type` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字典类型',
  `allow_roles` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '允许查看该字段的角色',
  `options` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '字段其他设置',
  `sort` tinyint unsigned DEFAULT '0' COMMENT '排序',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务字段表';

-- ----------------------------
-- Records of sa_tool_generate_columns
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_tool_generate_tables
-- ----------------------------
DROP TABLE IF EXISTS `sa_tool_generate_tables`;
CREATE TABLE `sa_tool_generate_tables` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `table_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '表名称',
  `table_comment` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '表注释',
  `stub` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'stub类型',
  `template` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '模板名称',
  `namespace` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '命名空间',
  `package_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '控制器包名',
  `business_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务名称',
  `class_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '类名称',
  `menu_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成菜单名',
  `belong_menu_id` int DEFAULT NULL COMMENT '所属菜单',
  `tpl_category` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成类型,single 单表CRUD,tree 树表CRUD,parent_sub父子表CRUD',
  `generate_type` smallint DEFAULT '1' COMMENT '1 压缩包下载 2 生成到模块',
  `generate_path` varchar(100) COLLATE utf8mb4_general_ci DEFAULT 'saiadmin-artd' COMMENT '前端根目录',
  `generate_model` smallint DEFAULT '1' COMMENT '1 软删除 2 非软删除',
  `generate_menus` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成菜单列表',
  `build_menu` smallint DEFAULT '1' COMMENT '是否构建菜单',
  `component_type` smallint DEFAULT '1' COMMENT '组件显示方式',
  `options` varchar(1500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其他业务选项',
  `form_width` int DEFAULT '800' COMMENT '表单宽度',
  `is_full` tinyint(1) DEFAULT '1' COMMENT '是否全屏',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `source` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据源',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务表';

-- ----------------------------
-- Records of sa_tool_generate_tables
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_treatment_plan
-- ----------------------------
DROP TABLE IF EXISTS `sa_treatment_plan`;
CREATE TABLE `sa_treatment_plan` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL COMMENT '患者ID',
  `doctor_id` int NOT NULL DEFAULT '0' COMMENT '创建医生的ID(0代表AI创建)',
  `title` varchar(100) NOT NULL COMMENT '计划大标题（如：戒除前90天计划）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=进行中, 2=已完成, 3=终止',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_member_status` (`member_id`,`status`),
  KEY `idx_doctor_status` (`doctor_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='治疗计划表';

-- ----------------------------
-- Records of sa_treatment_plan
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for sa_treatment_stage
-- ----------------------------
DROP TABLE IF EXISTS `sa_treatment_stage`;
CREATE TABLE `sa_treatment_stage` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` int NOT NULL COMMENT '所属计划ID',
  `member_id` int NOT NULL COMMENT '患者ID冗余',
  `stage_name` varchar(50) NOT NULL COMMENT '阶段名称（如：第一阶段评估）',
  `start_date` date NOT NULL COMMENT '起止日期-开始',
  `end_date` date NOT NULL COMMENT '起止日期-结束',
  `stage_target` varchar(255) DEFAULT NULL COMMENT '阶段目标',
  `sort` int NOT NULL DEFAULT '100' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0=待开始 1=进行中 2=完成',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_plan_sort` (`plan_id`,`sort`),
  KEY `idx_member_status` (`member_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='治疗计划阶段表';

-- ----------------------------
-- Records of sa_treatment_stage
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for saiai_chat
-- ----------------------------
DROP TABLE IF EXISTS `saiai_chat`;
CREATE TABLE `saiai_chat` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int DEFAULT NULL COMMENT '分组ID',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `role` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'user' COMMENT '角色',
  `model` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '模型名称',
  `content` text COLLATE utf8mb4_general_ci COMMENT '消息内容',
  `tokens` int DEFAULT '0' COMMENT '消耗token数',
  `ip` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'IP地址',
  `user_agent` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'User Agent',
  `created_by` int DEFAULT NULL COMMENT '创建人',
  `updated_by` int DEFAULT NULL COMMENT '修改人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_session_id` (`group_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='AI对话记录表';

