  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置名称',
  `type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台类型: gemini, openai, deepseek',
  `ai_key` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'API Key',
  `base_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '接口地址',
  `model` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型名称',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认: 1是,0否',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='AI配置表';

